changeSet.sql:
ALTER TABLE configuracao_sistema ADD CONSTRAINT ck_configuracao_sistema_segredo
    CHECK (NOT sensivel OR valor = '' OR valor ~ '^v1:[A-Za-z0-9+/]{39,}={0,2}$');
