rollback.sql:
DO $$ BEGIN
    IF EXISTS (SELECT 1 FROM configuracao_sistema WHERE servico <> 'SISTEMA' AND valor <> '') THEN
        RAISE EXCEPTION 'Preserve as configurações de serviços antes da reversão.';
    END IF;
END $$;

DELETE FROM configuracao_sistema WHERE id IN ('cd9d9b90-51a1-4e9e-a788-61c8c44cee71',
    '169aa882-56a1-4dc0-8f18-f91f020eae45', '81caad2e-d957-465d-8b0a-e283b5a7e26c');
ALTER TABLE configuracao_sistema DROP CONSTRAINT ck_configuracao_sistema_segredo;
